func (s *Server) handleStreamRequest(
	w http.ResponseWriter, r *http.Request, sessKey string, sess app.Session,
	subjects []string,
	onOpen func(
		streamID uint64,
		sse *datastar.ServerSentEventGenerator,
	) error,
	onClose func(streamID uint64),
	fn func(
		streamID uint64,
		sse *datastar.ServerSentEventGenerator,
		ch <-chan msgbroker.Message,
	),
) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	streamID := s.streamSeq.Add(1)
	sse := datastar.NewSSE(w, r, datastar.WithCompression())

	ctx := r.Context()
	sub, err := s.messageBroker.Subscribe(ctx, s.messageBrokerMetrics, subjects...)
	if err != nil {
		s.httpErrIntern(w, r, sse, "subscribing to message broker", err)
		return
	}

	subC := sub.C()
	if onOpen != nil {
		if err := onOpen(streamID, sse); err != nil {
			sub.Close()
			s.httpErrIntern(w, r, sse, "handling stream open hook", err)
			return
		}
	}
	sessionClosed := make(chan struct{})

	if sess.UserID != "" {
		ctx, cancel := context.WithCancel(ctx)
		defer cancel()
		if err := s.sessionManager.NotifyClosed(ctx, sessKey, func() {
			close(sessionClosed)
		}); err != nil {
			// The open hook already ran. This stream holds whatever it took:
			// a subscription, and on a stateful page an instance.
			// The watchdog below is what usually gives those back and it does
			// not exist yet.
			sub.Close()
			if onClose != nil {
				onClose(streamID)
			}
			s.httpErrIntern(w, r, sse, "setting up session closure watcher", err)
			return
		}
	}

	go func() {
		select {
		case <-sessionClosed:
		case <-r.Context().Done():
		case <-s.shutdownCh:
		}
		sub.Close()
		if onClose != nil {
			// Not the goroutine net/http recovers.
			defer func() {
				if rec := recover(); rec != nil {
					s.logErr("recovering panic in stream close hook",
						fmt.Errorf("%v\n%s", rec, debug.Stack()))
				}
			}()
			onClose(streamID)
		}
	}()

	fn(streamID, sse, subC)
}

type Server struct {
	shutdownCh           chan struct{} // Closed when shutting down.
	shutdownOnce         sync.Once
	runCancel            context.CancelFunc
	httpServer           *http.Server
	messageBroker        msgbroker.MessageBroker
	messageBrokerMetrics brokerMetrics
	streamSeq            atomic.Uint64
	app                  *app.App
	mux                  *http.ServeMux
	logger               *slog.Logger
	middleware           []func(http.Handler) http.Handler
	datastarJSSrc        string
	enabledTLS           bool

	authConf              *AuthConfig
	sessionTokenGenerator sessmanager.TokenGenerator
	sessionManager        sessmanager.SessionManager[app.Session]
	csrfConf              *CSRFConfig
	stateConf             *StateConfig
}

// NewServer creates a new server instance.
// Supported options:
//
//   - WithMiddleware
//   - WithHTTPServer
//   - WithAssets
//   - WithDatastarJS
//   - WithCSRFProtection
func NewServer(
	app *app.App,
	messageBroker msgbroker.MessageBroker,
	sessionManager sessmanager.SessionManager[app.Session],
	opts ...ServerOption,
) *Server {
	s := &Server{
		shutdownCh: make(chan struct{}),
		httpServer: &http.Server{
			// Time to read request headers + body
			ReadTimeout: DefaultHTTPReadTimeout,
			// Time to read just headers (helps prevent Slowloris attacks)
			ReadHeaderTimeout: DefaultHTTPReadHeaderTimeout,
			// Time to write response
			WriteTimeout: DefaultHTTPWriteTimeout,
			// Time to wait for next request when using keep-alive
			IdleTimeout:    DefaultHTTPIdleTimeout,
			MaxHeaderBytes: DefaultHTTPMaxHeaderBytes,
		},
		app:                  app,
		mux:                  http.NewServeMux(),
		middleware:           []func(http.Handler) http.Handler{},
		messageBroker:        messageBroker,
		messageBrokerMetrics: brokerMetrics{},
		sessionManager:       sessionManager,
	}

	// Apply options
	for _, opt := range opts {
		if err := opt(s); err != nil {
			panic(fmt.Errorf("applying server option: %w", err))
		}
	}

	// Reverse handlers such that they're invoked in the order of definition.
	slices.Reverse(s.middleware)

	if s.sessionManager == nil {
		panic("missing SessionManager")
	}
	if s.authConf == nil {
		s.authConf = &AuthConfig{
			TokenCookie: AuthSessionConfigTokenCookie{
				Name: DefaultAuthSessionCookieName,
			},
		}
	}
	if s.sessionTokenGenerator == nil {
		s.sessionTokenGenerator = sesstokgen.Generator{
			Length: sesstokgen.DefaultLength,
		}
	}

	// Use defaults if not set.
	if s.datastarJSSrc == "" {
		s.datastarJSSrc = DefaultDatastarJSSrc
	}
	if s.logger == nil {
		opt := &slog.HandlerOptions{
			Level: slog.LevelInfo,
		}
		if IsDevMode() {
			opt.Level = slog.LevelDebug
		}
		s.logger = slog.New(slog.NewJSONHandler(os.Stderr, opt))
	}
	href.SetLogger(s.logger)
	s.httpServer.Handler = s
	if s.httpServer.ErrorLog == nil {
		s.httpServer.ErrorLog = slog.NewLogLogger(
			slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{}),
			slog.LevelInfo,
		)
	}
	if s.messageBroker == nil {
		panic("missing message broker")
	}
	if si, ok := s.messageBroker.(msgbroker.StreamInitializer); ok {
		if err := si.InitStreams(MessageBrokerStreamSubjects()); err != nil {
			panic(fmt.Sprintf("initializing message broker streams: %v", err))
		}
	}
	if s.stateConf == nil {
		panic("missing state config: this app has stateful pages, " +
			"pass WithStateConfig to NewServer")
	}
	if s.csrfConf == nil {
		panic("missing option WithCSRFProtection")
	} else if s.csrfConf != nil && s.csrfConf.TokenManager == nil {
		panic("CSRFConfig.TokenManager is nil")
	}

	setupHandlers(s)

	return s
}

const (
	EvSubjNoticed = "noticed.*"

	// Public events:

	EvSubjRoomPosted = "room.posted.*"
	EvSubjTicked     = "ticked"
)

const (
	EvSubjPrefNoticed    = "noticed."
	EvSubjPrefRoomPosted = "room.posted."
)

func MessageBrokerStreamSubjects() []string {
	return []string{
		EvSubjNoticed,
		EvSubjRoomPosted,
		EvSubjTicked,
	}
}

func evSubjPageRooms(userID string, subjRoom string) []string {
	return []string{
		"noticed." + userID,
		"room.posted." + subjRoom,
	}
}

func evSubjPageTabs(userID string) []string {
	if userID == "" {
		return []string{
			EvSubjTicked,
		}
	}
	return []string{
		EvSubjTicked,
		"noticed." + userID,
	}
}

type CSRFConfig struct {
	TokenManager csrf.TokenManager

	// DevBypassToken, if non-empty, is accepted as a valid
	// CSRF token for any session. Use this only in development
	// to allow tools like k6 to exercise POST endpoints.
	DevBypassToken string
}

// WithCSRFProtection enables Cross-Site-Request-Forgery protection on
// POST/PUT/PATCH/DELETE action endpoints. By default CSRF protection is disabled
// but will log a warning during server initialization time.
func WithCSRFProtection(conf CSRFConfig) ServerOption {
	return func(s *Server) error {
		if conf.TokenManager == nil {
			return errors.New("nil CSRF token manager")
		}
		if conf.DevBypassToken != "" && !IsDevMode() {
			return errors.New("CSRF dev bypass token must not be set in non-dev mode")
		}
		s.csrfConf = &conf
		return nil
	}
}

// --- Auth ---

const DefaultAuthSessionCookieName = "sessiontoken"

type AuthConfig struct {
	// SessionTokenGenerator is optional; defaults to sesstokgen.Generator
	SessionTokenGenerator sessmanager.TokenGenerator

	// TokenCookie is optional; defaults to DefaultAuthSessionCookieName
	TokenCookie AuthSessionConfigTokenCookie

	// DisableHTTPOnly is optional; By default, httponly is enabled.
	DisableHTTPOnly bool
}

type AuthSessionConfigTokenCookie struct {
	// Name is optional; Default is DefaultAuthSessionCookieName
	Name string
	// Domain is optional; Not set by default.
	Domain string
}

// WithAuth sets session-based authentication configuration.
func WithAuth(o AuthConfig) ServerOption {
	return func(s *Server) error {
		if o.TokenCookie.Name == "" {
			o.TokenCookie.Name = DefaultAuthSessionCookieName
		}
		s.authConf = &o
		s.sessionTokenGenerator = o.SessionTokenGenerator
		return nil
	}
}

func (s *Server) setSessionCookie(w http.ResponseWriter, value string) {
	cookie := http.Cookie{
		Name:     s.authConf.TokenCookie.Name,
		Value:    value,
		Path:     "/",
		Domain:   s.authConf.TokenCookie.Domain,
		HttpOnly: !s.authConf.DisableHTTPOnly,
		Secure:   s.enabledTLS,
		SameSite: http.SameSiteLaxMode,
	}
	if value == "" {
		cookie.MaxAge = -1
		cookie.Expires = time.Unix(0, 0)
	}
	http.SetCookie(w, &cookie)
}

// authSess reads the session token from r and checks CSRF when necessary.
// If onClose != nil it will be closed once the session is closed.
func (s *Server) auth(
	w http.ResponseWriter, r *http.Request,
) (sess app.Session, token string, ok bool) {
	c, err := r.Cookie(s.authConf.TokenCookie.Name)
	if err != nil {
		if errors.Is(err, http.ErrNoCookie) {
			return sess, "", true
		}
		return sess, "", false
	}

	sess, token, userID, ok, err := s.sessionManager.ReadSessionFromCookie(c)
	if err != nil {
		// Transient backend failure; keep the cookie, fail the request.
		http.Error(w, "Service Unavailable", http.StatusServiceUnavailable)
		return app.Session{}, "", false
	}
	if !ok {
		// Cookie is stale or malformed; clear it and continue as unauthenticated.
		s.setSessionCookie(w, "")
		return app.Session{}, "", true
	}
	sess.UserID = userID

	if !s.checkCSRF(w, r, sess) {
		return sess, token, false
	}

	return sess, token, true
}

// stateHMACKeyMinLen is the shortest key WithStateConfig accepts,
// the output size of the hash the key is used with.
const stateHMACKeyMinLen = 32

// StateConfig configures the per-page-instance server-side state runtime.
// Pass via WithStateConfig when at least one handler takes state *T.
type StateConfig struct {
	// HMACKey signs the Datapages-Instance identifier that rides on
	// request/response headers. Required; 32 bytes or more.
	// Rotating the key invalidates all live instances. A client whose
	// request is rejected reloads the page once and starts a fresh instance;
	// what it had not sent is lost.
	//
	// Give this purpose a key of its own, 32 random bytes or more. Sharing one key
	// across subsystems makes the security of each of them the security of all.
	HMACKey []byte

	// GracePeriod is how long a stateful instance survives after its SSE stream closes,
	// waiting for the client to reconnect (e.g. after a transient network blip).
	// Default 30s.
	GracePeriod time.Duration

	// MaxConcurrentInstances caps how many instances exist at the same time,
	// across all state types. A page load plus an SSE connect creates one,
	// which anyone who reaches the server can ask for. An instance keeps its
	// place for GracePeriod after its stream closes. Stream opens beyond the cap fail.
	// Default 10_000.
	MaxConcurrentInstances int
}

// WithStateConfig enables the per-page-instance server-side state runtime.
// Required when at least one handler takes state *T.
//
// On multi-server deployments the load balancer MUST route requests for a
// given client consistently to the same backend (sticky sessions),
// since state lives in process memory.
func WithStateConfig(conf StateConfig) ServerOption {
	return func(s *Server) error {
		// The bound is the output size of SHA-256, which is what RFC 2104
		// asks of a key. It catches a short literal and nothing else:
		// length is not entropy, and 32 bytes derived from one weak
		// passphrase pass this check.
		if len(conf.HMACKey) < stateHMACKeyMinLen {
			return fmt.Errorf(
				"WithStateConfig: HMACKey must be at least %d bytes, got %d",
				stateHMACKeyMinLen, len(conf.HMACKey))
		}
		if conf.GracePeriod <= 0 {
			conf.GracePeriod = 30 * time.Second
		}
		if conf.MaxConcurrentInstances <= 0 {
			conf.MaxConcurrentInstances = 10_000
		}
		s.stateConf = &conf
		return nil
	}
}

// stateInstanceIDHeader is the request/response header used to carry the
// server-issued per-page-instance identifier.
const stateInstanceIDHeader = "Datapages-Instance"

// stateRetryHeader signals the client to reconnect before retrying an
// action that was rejected because no live instance was found.
const stateRetryHeader = "Datapages-Retry"

// stateRetryReconnect is the only value currently emitted on stateRetryHeader.
const stateRetryReconnect = "reconnect"

// stateInstanceIDSep separates payload and signature in a Datapages-Instance value.
// It must not be "." and must not appear in the base64url alphabet:
// the identifier is used verbatim as a single message-broker subject token
// (see the SubjectStateID event routing), and "." would split it in two,
// breaking single-token wildcard matching.
const stateInstanceIDSep = '~'

// stateInstanceIDTag and the tag stateRouteKey writes name what each MAC is for.
// One key, two derivations: without a tag of its own on each,
// a value computed for one of them is a value the other would accept.
var stateInstanceIDTag = []byte("datapages-instance\x00")

// signStateInstanceID produces an HMAC-signed Datapages-Instance value.
// The payload is 16 random bytes; the output is:
// base64url(payload) + "~" + base64url(hmacSHA256(tag, payload)).
func (s *Server) signStateInstanceID() (string, error) {
	if s.stateConf == nil {
		return "", errors.New("state runtime not configured")
	}
	var payload [16]byte
	if _, err := rand.Read(payload[:]); err != nil {
		return "", err
	}
	mac := hmac.New(sha256.New, s.stateConf.HMACKey)
	mac.Write(stateInstanceIDTag)
	mac.Write(payload[:])
	return base64.RawURLEncoding.EncodeToString(payload[:]) +
		string(stateInstanceIDSep) +
		base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
}

// verifyStateInstanceID returns true when the supplied Datapages-Instance
// value is well-formed and signed by the server's HMAC key.
func (s *Server) verifyStateInstanceID(id string) bool {
	if s.stateConf == nil || id == "" {
		return false
	}
	sep := strings.IndexByte(id, stateInstanceIDSep)
	if sep <= 0 || sep == len(id)-1 {
		return false
	}
	payload, err := base64.RawURLEncoding.DecodeString(id[:sep])
	if err != nil {
		return false
	}
	sig, err := base64.RawURLEncoding.DecodeString(id[sep+1:])
	if err != nil {
		return false
	}
	mac := hmac.New(sha256.New, s.stateConf.HMACKey)
	mac.Write(stateInstanceIDTag)
	mac.Write(payload)
	return hmac.Equal(mac.Sum(nil), sig)
}

// stateRouteKey derives the value that names a tab in message broker subjects.
// Subjects travel further than a request does: into broker logs,
// stream storage, traces and metrics. The Datapages-Instance id itself
// stays out of them, since presenting it is what claims a tab's state.
// Knowing the routing key only lets a dispatcher address that tab.
//
// Callers must verify the id first.
func (s *Server) stateRouteKey(id string) string {
	mac := hmac.New(sha256.New, s.stateConf.HMACKey)
	mac.Write([]byte("datapages-route\x00"))
	mac.Write([]byte(id))
	return base64.RawURLEncoding.EncodeToString(mac.Sum(nil)[:16])
}

// stateLiveInstances counts the instances of every state type.
// Memory is shared between them,
// and so is the budget in StateConfig.MaxConcurrentInstances.
var stateLiveInstances atomic.Int64

// stateReserveInstance takes one slot out of the budget. It reports false
// when the server is full, which fails the stream open that asked for it.
func (s *Server) stateReserveInstance() bool {
	if stateLiveInstances.Add(1) > int64(s.stateConf.MaxConcurrentInstances) {
		stateLiveInstances.Add(-1)
		return false
	}
	return true
}

// stateHasCapacity reports whether the budget has room right now.
// It is a look, not a claim, and callers use it before a stream commits its status line.
// stateReserveInstance is what actually holds the bound.
func (s *Server) stateHasCapacity() bool {
	return stateLiveInstances.Load() < int64(s.stateConf.MaxConcurrentInstances)
}

// errStateAtCapacity fails a stream open that finds no free instance.
var errStateAtCapacity = errors.New("state instance limit reached")

// stateStoreShards is how many independent maps a stateStore spreads its keys over.
// Instance ids are random, so they distribute evenly,
// and each shard carries its own lock.
const stateStoreShards = 32

// stateStoreSeed randomizes shard selection per process.
var stateStoreSeed = maphash.MakeSeed()

// stateStoreShard is one lock and the keys that belong to it.
type stateStoreShard[S any] struct {
	mu sync.RWMutex
	m  map[string]*S
}

// stateStore maps a verified Datapages-Instance id to the live slot it names.
//
// Every key is written once and deleted once, and none is read after its deletion.
// That is the opposite of what sync.Map is tuned for,
// which is a read-mostly set of stable keys. Sharded plain maps read without a write
// barrier and delete without leaving a tombstone behind.
//
// The zero value is ready to use.
type stateStore[S any] struct {
	shards [stateStoreShards]stateStoreShard[S]
}

func (s *stateStore[S]) shard(id string) *stateStoreShard[S] {
	return &s.shards[maphash.String(stateStoreSeed, id)%stateStoreShards]
}

// Load returns the slot registered under id, or (nil, false).
func (s *stateStore[S]) Load(id string) (*S, bool) {
	sh := s.shard(id)
	sh.mu.RLock()
	slot, ok := sh.m[id]
	sh.mu.RUnlock()
	return slot, ok
}

// Store registers slot under id, replacing whatever was there.
func (s *stateStore[S]) Store(id string, slot *S) {
	sh := s.shard(id)
	sh.mu.Lock()
	if sh.m == nil {
		sh.m = make(map[string]*S)
	}
	sh.m[id] = slot
	sh.mu.Unlock()
}

// CompareAndDelete removes id only while it still names slot.
// A stream can allocate a fresh slot under an id whose predecessor is on its way out,
// and the one leaving must not take the new one with it.
func (s *stateStore[S]) CompareAndDelete(id string, slot *S) bool {
	sh := s.shard(id)
	sh.mu.Lock()
	defer sh.mu.Unlock()
	if sh.m[id] != slot {
		return false
	}
	delete(sh.m, id)
	return true
}

// stateSlotStateTab holds one instance of StateTab.
// It is checked out of statePoolStateTab on StreamOpen and returned
// when StreamClose elapses without a reconnect within GracePeriod.
type stateSlotStateTab struct {
	state    *app.StateTab
	mu       sync.Mutex  // serializes all stateful handler calls on this instance
	streamID uint64      // currently-associated SSE stream (0 when detached)
	timer    *time.Timer // grace-period timer; nil while a stream is attached
	dead     bool        // true once the state went back to the pool
}

// statePoolStateTab pools StateTab values across instance checkouts.
// Every value is zeroed before it is handed out, so nothing of the
// previous tab reaches the next one.
var statePoolStateTab = sync.Pool{
	New: func() any { return new(app.StateTab) },
}

// stateInstancesStateTab maps a verified Datapages-Instance id to the live slot.
var stateInstancesStateTab stateStore[stateSlotStateTab]

// allocateStateTab checks a state value out of statePoolStateTab, zeroes it, registers it
// under id, and attaches it to the given SSE streamID.
// Returns the slot so callers (StreamOpen) can pass the state to the user,
// or nil when the server holds as many instances as it may.
func (s *Server) allocateStateTab(id string, streamID uint64) *stateSlotStateTab {
	if !s.stateReserveInstance() {
		return nil
	}
	st := statePoolStateTab.Get().(*app.StateTab)
	*st = app.StateTab{} // nothing of the previous tab survives
	slot := &stateSlotStateTab{state: st, streamID: streamID}
	stateInstancesStateTab.Store(id, slot)
	return slot
}

// lookupStateTab returns the registered slot for id, or (nil, false)
// when no live instance matches. The id is not HMAC-verified here;
// call verifyStateInstanceID first.
func (s *Server) lookupStateTab(id string) (*stateSlotStateTab, bool) {
	return stateInstancesStateTab.Load(id)
}

// reconnectStateTab tries to reattach an existing slot (grace-period reconnect)
// to a new SSE streamID. Returns (slot, true) on success; (nil, false)
// when the id is unknown (e.g. grace period already elapsed).
// A slot whose state already went back to the pool is refused.
func (s *Server) reconnectStateTab(id string, streamID uint64) (*stateSlotStateTab, bool) {
	slot, ok := s.lookupStateTab(id)
	if !ok {
		return nil, false
	}
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		return nil, false
	}
	if slot.timer != nil {
		slot.timer.Stop()
		slot.timer = nil
	}
	slot.streamID = streamID
	return slot, true
}

// closeStreamStateTab marks id as detached from streamID and starts
// the grace timer. If the client reconnects with the same id
// before the timer fires, the slot is reused as-is.
//
// A tab can hold two streams at once while the server still
// tears the older one down. Only the attached stream may detach.
func (s *Server) closeStreamStateTab(id string, streamID uint64) {
	slot, ok := s.lookupStateTab(id)
	if !ok {
		return
	}
	slot.mu.Lock()
	if slot.streamID != streamID {
		slot.mu.Unlock()
		return
	}
	slot.streamID = 0
	if slot.timer != nil {
		slot.timer.Stop()
	}
	slot.timer = time.AfterFunc(s.stateConf.GracePeriod, func() {
		slot.mu.Lock()
		// A stream reattached while this timer was already running,
		// or another timer got here first.
		if slot.streamID != 0 || slot.dead {
			slot.mu.Unlock()
			return
		}
		slot.dead = true
		st := slot.state
		slot.state = nil
		slot.mu.Unlock()
		// A stream can allocate a fresh slot under this id while this
		// one is on its way out. Drop only the slot this timer owns.
		stateInstancesStateTab.CompareAndDelete(id, slot)
		stateLiveInstances.Add(-1)
		if st != nil {
			statePoolStateTab.Put(st)
		}
	})
	slot.mu.Unlock()
}

func setupHandlers(s *Server) {
	// Pages
	s.mux.HandleFunc(
		"GET /",
		s.handlePageIndexGET)
	s.mux.HandleFunc(
		"GET /rooms/{$}",
		s.handlePageRoomsGET)
	s.mux.HandleFunc(
		"GET /rooms/_$/{$}",
		s.handlePageRoomsGETStream)
	s.mux.HandleFunc(
		"GET /rooms/_$/anon/{$}",
		s.handlePageRoomsGETStreamAnon)
	s.mux.HandleFunc(
		"GET /tabs/{$}",
		s.handlePageTabsGET)
	s.mux.HandleFunc(
		"GET /tabs/_$/{$}",
		s.handlePageTabsGETStream)
	s.mux.HandleFunc(
		"GET /tabs/_$/anon/{$}",
		s.handlePageTabsGETStreamAnon)
	s.mux.HandleFunc(
		"POST /rooms/post/{$}",
		s.handlePageRoomsPOSTPost)
	s.mux.HandleFunc(
		"POST /rooms/notice/{$}",
		s.handlePageRoomsPOSTNotice)
	s.mux.HandleFunc(
		"POST /tabs/bump/{$}",
		s.handlePageTabsPOSTBump)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	_ *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.logErr(msg, err)
	switch {
	case errors.Is(err, httperr.BadRequest):
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
	case errors.Is(err, httperr.Forbidden):
		http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
	case errors.Is(err, httperr.NotFound):
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
	case errors.Is(err, httperr.Conflict):
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
	default:
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
	}
}

func (s *Server) handlePageIndexGET(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}

	p := app.PageIndex{
		App: s.app,
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}

	if err := s.writeHTML(
		w, r, app.Session{}, genericHead, nil, body, bodyAttrs, nil,
	); err != nil {
		s.logErr("rendering PageIndex", err)
		return
	}
}

