func (s *Server) handlePageRoomsGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.auth(w, r)
	if !ok {
		return
	}

	if sess.UserID == "" {
		// The query carries the signals a stream subscribes by,
		// which the anonymous route needs as much as this one.
		target := r.URL.Path + "/anon"
		if r.URL.RawQuery != "" {
			target += "?" + r.URL.RawQuery
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
		return
	}

	var subjSignals struct {
		Room string `json:"room"`
	}
	if err := datastar.ReadSignals(r, &subjSignals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}
	if subjSignals.Room == "" {
		s.httpErrBad(w, "missing required signal", fmt.Errorf("signal %q is required", "room"))
		return
	}

	p := app.PageRooms{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageRooms(sess.UserID, subjSignals.Room),
		nil,
		nil,
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch {
				case strings.HasPrefix(msg.Subject, EvSubjPrefRoomPosted):
					var e app.EventRoomPosted
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventRoomPosted JSON", err)
						continue
					}
					if err := p.OnRoomPosted(e, sse); err != nil {
						s.logErr("handling PageRooms.OnRoomPosted", err)
					}
				case strings.HasPrefix(msg.Subject, EvSubjPrefNoticed):
					var e app.EventNoticed
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventNoticed JSON", err)
						continue
					}
					if err := p.OnNoticed(e, sse); err != nil {
						s.logErr("handling PageRooms.OnNoticed", err)
					}
				}
			}
		})
}

func (s *Server) handlePageRoomsGETStreamAnon(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.auth(w, r)
	if !ok {
		return
	}

	if sess.UserID != "" {
		s.httpErrBad(w, "authenticated client on anonymous stream", nil)
		return
	}

	var subjSignals struct {
		Room string `json:"room"`
	}
	if err := datastar.ReadSignals(r, &subjSignals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}
	if subjSignals.Room == "" {
		s.httpErrBad(w, "missing required signal", fmt.Errorf("signal %q is required", "room"))
		return
	}

	p := app.PageRooms{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageRooms(sess.UserID, subjSignals.Room),
		nil,
		nil,
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch {
				case strings.HasPrefix(msg.Subject, EvSubjPrefRoomPosted):
					var e app.EventRoomPosted
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventRoomPosted JSON", err)
						continue
					}
					if err := p.OnRoomPosted(e, sse); err != nil {
						s.logErr("handling PageRooms.OnRoomPosted", err)
					}
				}
			}
		})
}

func (s *Server) handlePageRoomsPOSTPost(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		Room string `json:"room"`
		Text string `json:"text"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	dispatch := func(
		e1 app.EventRoomPosted,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventRoomPosted JSON: %w", err)
			}
			p0 := e1.SubjectRoom
			subj := "room.posted." + p0
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, subj, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", subj, err)
			}
		}
		return nil
	}
	p := app.PageRooms{
		App: s.app,
	}
	err := p.POSTPost(r, signals, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageRooms.Post", err)
		return
	}
}

func (s *Server) handlePageRoomsPOSTNotice(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		User string `json:"user"`
		Text string `json:"text"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	dispatch := func(
		e1 app.EventNoticed,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventNoticed JSON: %w", err)
			}
			for _, p0 := range e1.SubjectUser {
				subj := "noticed." + p0
				err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, subj, j)
				if err != nil {
					return fmt.Errorf("publishing subject %q: %w", subj, err)
				}
			}
		}
		return nil
	}
	p := app.PageRooms{
		App: s.app,
	}
	err := p.POSTNotice(r, signals, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageRooms.Notice", err)
		return
	}
}

func (s *Server) handlePageTabsGET(w http.ResponseWriter, r *http.Request) {

	// Mint the per-instance identifier for this page load.
	// The client echoes this value on action requests and on the SSE
	// stream connect via the Datapages-Instance header.
	instanceID, err := s.signStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// The page carries an identifier that stands for one tab's state.
	// A cache that hands it to a second visitor hands over the state.
	w.Header().Set("Cache-Control", "no-store")

	p := app.PageTabs{
		App: s.app,
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageTabs.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}

	bodySuffix := func(w http.ResponseWriter) {
	}

	if err := s.writeHTML(
		w, r, app.Session{}, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageTabs", err)
		return
	}
}

func (s *Server) handlePageTabsGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.auth(w, r)
	if !ok {
		return
	}

	if sess.UserID == "" {
		// The query carries the signals a stream subscribes by,
		// which the anonymous route needs as much as this one.
		target := r.URL.Path + "/anon"
		if r.URL.RawQuery != "" {
			target += "?" + r.URL.RawQuery
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupStateTab(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	var slot *stateSlotStateTab

	p := app.PageTabs{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageTabs(sess.UserID),
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator,
		) error {
			if existing, ok := s.reconnectStateTab(instanceID, streamID); ok {
				slot = existing
			} else {
				slot = s.allocateStateTab(instanceID, streamID)
			}
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			// The close hook is wired up only once this one has returned nil.
			// An open that ends any other way hands the instance to the grace
			// timer here, since nothing else is left to give it back.
			opened := false
			defer func() {
				if !opened {
					s.closeStreamStateTab(instanceID, streamID)
				}
			}()
			slot.mu.Lock()
			defer slot.mu.Unlock()
			if err := p.StreamOpen(r, streamID, slot.state); err != nil {
				return err
			}
			opened = true
			return nil
		},
		func(streamID uint64) {
			s.closeStreamStateTab(instanceID, streamID)
		},
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch {
				case msg.Subject == EvSubjTicked:
					var e app.EventTicked
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventTicked JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnTicked(e, sse, slot.state); err != nil {
						s.logErr("handling PageTabs.OnTicked", err)
					}
					slot.mu.Unlock()
				case strings.HasPrefix(msg.Subject, EvSubjPrefNoticed):
					var e app.EventNoticed
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventNoticed JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnNoticed(e, sse, slot.state); err != nil {
						s.logErr("handling PageTabs.OnNoticed", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

func (s *Server) handlePageTabsGETStreamAnon(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.auth(w, r)
	if !ok {
		return
	}

	if sess.UserID != "" {
		s.httpErrBad(w, "authenticated client on anonymous stream", nil)
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupStateTab(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	var slot *stateSlotStateTab

	p := app.PageTabs{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageTabs(sess.UserID),
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator,
		) error {
			if existing, ok := s.reconnectStateTab(instanceID, streamID); ok {
				slot = existing
			} else {
				slot = s.allocateStateTab(instanceID, streamID)
			}
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			// The close hook is wired up only once this one has returned nil.
			// An open that ends any other way hands the instance to the grace
			// timer here, since nothing else is left to give it back.
			opened := false
			defer func() {
				if !opened {
					s.closeStreamStateTab(instanceID, streamID)
				}
			}()
			slot.mu.Lock()
			defer slot.mu.Unlock()
			if err := p.StreamOpen(r, streamID, slot.state); err != nil {
				return err
			}
			opened = true
			return nil
		},
		func(streamID uint64) {
			s.closeStreamStateTab(instanceID, streamID)
		},
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch msg.Subject {
				case EvSubjTicked:
					var e app.EventTicked
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventTicked JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnTicked(e, sse, slot.state); err != nil {
						s.logErr("handling PageTabs.OnTicked", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

func (s *Server) handlePageTabsPOSTBump(
	w http.ResponseWriter, r *http.Request,
) {
	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	slot, ok := s.lookupStateTab(instanceID)
	if !ok {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}

	dispatch := func(
		e1 app.EventTicked,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventTicked JSON: %w", err)
			}
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, EvSubjTicked, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", EvSubjTicked, err)
			}
		}
		return nil
	}
	p := app.PageTabs{
		App: s.app,
	}
	err := p.POSTBump(r, slot.state, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageTabs.Bump", err)
		return
	}
}
